input.command:
$exe = "D:\BenchRuns\C3-03\src\BatchRenameStudio\bin\Release\net8.0-windows\BatchRenameStudio.exe"
$w = "C:\Users\USER\AppData\Local\Temp\claude\D--BenchRuns-C3-03\305c9d83-c266-423c-b56e-1291371c7492\scratchpad\lead2"
foreach ($t in 1..3) { if (Test-Path "$w\t$t") { Remove-Item "$w\t$t" -Recurse -Force } ; New-Item -ItemType Directory -Force -Path "$w\t$t" | Out-Null }
foreach ($f in @("a.tar.gz",".gitignore","note","IMG_2.JPG","img_10.jpg")) { New-Item -ItemType File -Path "$w\t1\$f" | Out-Null }
foreach ($f in @("a1.txt","a2.txt","b.txt")) { New-Item -ItemType File -Path "$w\t2\$f" | Out-Null }
foreach ($f in @("f1.txt","f2.txt","f3.txt")) { New-Item -ItemType File -Path "$w\t3\$f" | Out-Null }
New-Item -ItemType Directory -Force -Path "$w\t1\subdir" | Out-Null
foreach ($t in 1..3) {
  Write-Output "===== T$t ====="
  $o = & $exe --plan --dir "$w\t$t" --rules "$w\r$t.json" --out "$w\p$t.json"
  Write-Output "exit=$LASTEXITCODE stdout=[$o]"
  Get-Content "$w\p$t.json" -Raw
  Write-Output "--- files after run: $((Get-ChildItem "$w\t$t" -File | Select-Object -ExpandProperty Name) -join ', ')"
}

